fn solve(t: Vec<char>) -> Vec<char> {
    let n = t.len();
    // Pre-allocate the output vector with the same capacity as the input.
    let mut out = Vec::with_capacity(n);
    // Use an index to walk through the input.
    let mut i = 0;
    while i < n {
        // At each step, push the corresponding character from `t` into `out`.
        out.push(t[i]);
        i += 1;
    }
    out
}

